-- MuleSetup: finishes the imported Mule pickup inside Roblox Studio.
-- Generated by tools/mule/build.py; edit the generator rather than this file.
--
-- Truck: 22.45 x 9.42 x 7.7 studs (length x width incl. mirrors x height), 97178 triangles.
--
-- Usage (server Script, after importing mule_pickup.fbx as a Model):
--     local MuleSetup = require(path.to.MuleSetup)
--     MuleSetup.Setup(workspace.Mule)                   -- materials, seats, colliders, welds
--     MuleSetup.SetLights(workspace.Mule, { Head = true, Tail = true })
--
-- Setup() is idempotent: running it twice leaves one set of seats/colliders/welds.

